"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["63126"],{65371(e){e.exports=JSON.parse('{"id":"F389","slug":"op-risk-capital-bia","name":"Operational Risk: Basic Indicator Capital and Expected Loss","subject":"Risk Management","section":"Risk","topic":"Operational risk and cyber risk","level":"Intermediate","aliases":["basic indicator approach","operational risk capital","loss frequency severity","op risk"],"formula":{"latex":"K_{BIA}=\\\\alpha\\\\times\\\\overline{GI}_{>0},\\\\quad EL=\\\\lambda\\\\times\\\\bar{L}","also":[],"text":"Basic Indicator capital = 15% x Average of the positive annual gross income over three years; Expected annual operational loss = Number of loss events per year x Average loss per event"},"symbols":[{"symbol":"alpha","meaning":"Fixed percentage of 15%","unit":"percent"},{"symbol":"GI","meaning":"Annual gross income","unit":"money"},{"symbol":"lambda","meaning":"Expected number of loss events per year (frequency)","unit":"number"},{"symbol":"L-bar","meaning":"Average loss per event (severity)","unit":"money"}],"when_to_use":"Use it for a simple measure of operational risk capital. The Basic Indicator Approach ties capital to income as a rough proxy for size. Most banks also model the frequency and severity of internal loss events to find the expected annual loss.","worked_example":{"problem":"A bank\'s gross income was 800, 900 and 950 million over three years. It averages 12 operational loss events a year, with an average loss of 0.4 million.","inputs":{"gi":[800,900,950],"alpha":15,"lam":12,"sev":0.4},"steps":[{"label":"Average of the positive gross income figures","working":null,"value":"883.3"},{"label":"Capital = alpha x average gross income","working":"0.15 x 883.333","value":"132.5"},{"label":"Expected annual loss = frequency x severity","working":"12 x 0.4","value":"4.80"}],"answer":"Average positive gross income is 883.3, so Basic Indicator capital is 132.5 million. Expected annual operational loss from the frequency and severity data is 4.80 million."},"calculator":{"available":true,"inputs":[{"id":"gi","label":"Gross income, last three years (millions)","unit":"money","type":"list","default":[800,900,950],"hint":""},{"id":"alpha","label":"Alpha","unit":"%","type":"number","default":15,"hint":""},{"id":"lam","label":"Loss events per year","unit":"number","type":"number","default":12,"hint":""},{"id":"sev","label":"Average loss per event (millions)","unit":"money","type":"number","default":0.4,"hint":""}],"checks":[{"expr":"sum(posl(gi))>0","message":"At least one year of gross income must be positive."}],"steps":[{"id":"avg","label":"Average of the positive gross income figures","expr":"sum(posl(gi))/max(sum(1 for x in gi if x>0), 1)","format":"num1"},{"id":"k","label":"Capital = alpha x average gross income","expr":"alpha*avg","format":"num1"},{"id":"el","label":"Expected annual loss = frequency x severity","expr":"lam*sev","format":"num2"}],"results":["k","el"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"avg":883.3333333,"k":132.499999999995,"el":4.8}},"finder":{"finds":"Capital and expected loss for operational risk","needs":"Gross income, loss frequency and severity"},"related":[{"slug":"annualized-loss-expectancy","name":"Annualized Loss Expectancy (Cyber Risk)"},{"slug":"expected-unexpected-loss","name":"Expected and Unexpected Credit Loss"}],"related_ids":["F388","F384"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>K</mi><mrow><mi>B</mi><mi>I</mi><mi>A</mi></mrow></msub><mo>=</mo><mi>\u03B1</mi><mo>\xd7</mo><msub><mover accent=\\"true\\"><mrow><mi>G</mi><mi>I</mi></mrow><mo stretchy=\\"true\\">\u203E</mo></mover><mrow><mo>&gt;</mo><mn>0</mn></mrow></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>E</mi><mi>L</mi><mo>=</mo><mi>\u03BB</mi><mo>\xd7</mo><mover accent=\\"true\\"><mi>L</mi><mo>\u02C9</mo></mover></mrow><annotation encoding=\\"application/x-tex\\">K_{BIA}=\\\\alpha\\\\times\\\\overline{GI}_{&gt;0},\\\\quad EL=\\\\lambda\\\\times\\\\bar{L}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msub><mi>K</mi><mrow><mi>B</mi><mi>I</mi><mi>A</mi></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle K_{BIA}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>\u03B1</mi><mo>\xd7</mo><msub><mover accent=\\"true\\"><mrow><mi>G</mi><mi>I</mi></mrow><mo stretchy=\\"true\\">\u203E</mo></mover><mrow><mo>&gt;</mo><mn>0</mn></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\alpha\\\\times\\\\overline{GI}_{&gt;0}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>E</mi><mi>L</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle EL</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>\u03BB</mi><mo>\xd7</mo><mover accent=\\"true\\"><mi>L</mi><mo>\u02C9</mo></mover></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\lambda\\\\times\\\\bar{L}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"working-capital-analysis","name":"Operating Working Capital Analysis"},"next":{"slug":"tangency-portfolio-two-assets","name":"Optimal Risky Portfolio (Maximum Sharpe, Two Assets)"},"lesson":null,"total":522}')}}]);